// JiranLink AI server. Generated by scripts/build-worker.ts from src/ai/spec.ts. Do not edit by hand.
//
// Holds the Gemini API key so the website never does. Runs on Vercel (api/, region pinned in vercel.json) or as a
// Cloudflare Worker (worker/worker.js). Set these as environment variables / secrets:
//   GEMINI_API_KEY   (Secret, required)
//   GEMINI_MODEL     (optional, default gemini-3.8-flash)
//   ALLOWED_ORIGINS  (optional, comma-separated; default the GitHub Pages site and local dev)
//
// Endpoints:
//   GET  /check     opens in a browser: confirms the key and model work  (on Vercel: /api/check, etc.)
//   POST /classify  { text }       -> { content }   search fallback: picks service categories
//   POST /agent     { contents }   -> { content }   "Ask JiranLink" assistant turn with tool calling

const DEFAULT_MODEL = "gemini-3.8-flash";
const FALLBACK_MODEL = "gemini-3.5-flash-lite";
const DEFAULT_ORIGINS = ["https://hengchuanquah.github.io", "http://localhost:5173", "http://localhost:4173", "http://localhost:4174"];

const CLASSIFY_PROMPT = "You classify short service requests from residents of Malaysian housing townships.\nRequests may be in English, Bahasa Malaysia, Chinese, or Manglish, and may describe a problem instead of naming a service.\nPick up to 3 categories from this list only, with a confidence score from 0 to 1 for each:\naircond: Aircond servicing & repair\nplumbing: Plumbing\nelectrical: Electrical wiring & lights\nhandyman: Handyman & small fixes\npainting: Painting & touch-ups\nappliance: Appliance repair\npest: Pest control\nlocksmith: Locksmith\ncleaning: Home cleaning\nlaundry: Laundry & ironing\ngardening: Gardening & lawn\ncarwash: Car wash at home\ncakes: Cakes & baking\nkuih: Kuih & traditional snacks\nmeals: Home-cooked meals & catering\ntuition: School tuition\nlanguage: Language lessons\nmusic: Music lessons\nquran: Quran & religious classes\ncoding: Computer & coding classes\nfitness: Fitness & sports coaching\nchildcare: Babysitting & childminding\neldercare: Eldercare & companionship\npetcare: Pet sitting & walking\npetgrooming: Pet grooming\nhaircut: Haircut at home\nbeauty: Makeup & beauty\ntailoring: Tailoring & alterations\nphoto: Photography & video\nerrands: Errands & grocery runs\nmoving: Moving & heavy lifting\ndevicerepair: Phone & computer help\ndesign: Design & printing\nAlso extract any time preference as short English text (e.g. \"Saturday morning\"), or null.\nSet online to true only if the person asks for an online or remote service.\nNever invent categories. Reply with JSON only, in this shape:\n{\"categories\":[{\"id\":\"plumbing\",\"score\":0.9}],\"timeHint\":null,\"online\":false}";
const AGENT_PROMPT = "You are the JiranLink assistant, inside a neighbour services app for Sime Darby Property townships in Malaysia.\nYou help a verified resident to: find a neighbour who offers a service, understand how JiranLink works, and check their own bookings.\n\nRules:\n- When the resident needs any service or describes a problem, call find_providers. Pass their words as \"need\" and the best category_id if you can tell. Do not ask them to clarify first; make your best guess.\n- When they ask how JiranLink works or how to do something, call get_help with the closest topic and answer only from what it returns.\n- When they ask about their bookings, call my_bookings.\n- Only mention providers that find_providers returned. Never invent providers, prices, ratings, rules or features.\n- If find_providers returns no providers, say so plainly and call draft_request with their need, so they can post it on the request board.\n- Reply in 1 to 3 short sentences. The app shows provider cards and buttons under your reply, so do not list every detail.\n- Reply in the language the resident used: English, Bahasa Malaysia, Chinese or Manglish.\n- If the question is not about JiranLink or local services, say you can only help with JiranLink.\n- Never ask for IC numbers, home addresses, passwords or payment details.\n\nService categories (id: name):\naircond: Aircond servicing & repair\nplumbing: Plumbing\nelectrical: Electrical wiring & lights\nhandyman: Handyman & small fixes\npainting: Painting & touch-ups\nappliance: Appliance repair\npest: Pest control\nlocksmith: Locksmith\ncleaning: Home cleaning\nlaundry: Laundry & ironing\ngardening: Gardening & lawn\ncarwash: Car wash at home\ncakes: Cakes & baking\nkuih: Kuih & traditional snacks\nmeals: Home-cooked meals & catering\ntuition: School tuition\nlanguage: Language lessons\nmusic: Music lessons\nquran: Quran & religious classes\ncoding: Computer & coding classes\nfitness: Fitness & sports coaching\nchildcare: Babysitting & childminding\neldercare: Eldercare & companionship\npetcare: Pet sitting & walking\npetgrooming: Pet grooming\nhaircut: Haircut at home\nbeauty: Makeup & beauty\ntailoring: Tailoring & alterations\nphoto: Photography & video\nerrands: Errands & grocery runs\nmoving: Moving & heavy lifting\ndevicerepair: Phone & computer help\ndesign: Design & printing";
const AGENT_TOOLS = [{"name":"find_providers","description":"Search JiranLink for verified neighbours who offer a service, ranked nearest first from the resident's home (same building, then precinct, township, then 2, 5 and 10 km), hiding providers rated below the quality floor. Returns at most a few providers plus any online ones.","parameters":{"type":"object","properties":{"need":{"type":"string","description":"What the resident needs, in their own words."},"category_id":{"type":"string","enum":["aircond","plumbing","electrical","handyman","painting","appliance","pest","locksmith","cleaning","laundry","gardening","carwash","cakes","kuih","meals","tuition","language","music","quran","coding","fitness","childcare","eldercare","petcare","petgrooming","haircut","beauty","tailoring","photo","errands","moving","devicerepair","design"],"description":"Best matching service category, if you can tell."}},"required":["need"]}},{"name":"get_help","description":"Get JiranLink's official help text for one topic, with buttons that take the resident to the right screen.","parameters":{"type":"object","properties":{"topic":{"type":"string","enum":["how_to_search","booking_steps","payment_options","pay_after_rule","cancelling","request_board","reviews","past_customer_reviews","verification","become_provider","provider_hours","visitor_pass","ranking","safety_report_block","messages"]}},"required":["topic"]}},{"name":"my_bookings","description":"List the resident's own current bookings and what each one is waiting for.","parameters":{"type":"object","properties":{}}},{"name":"draft_request","description":"Prepare a request-board post in the resident's words, for them to review and post. Use when no provider offers what they need.","parameters":{"type":"object","properties":{"text":{"type":"string","description":"The post, written as the resident asking neighbours for help."}},"required":["text"]}}];

// Best-effort limits. Each Cloudflare location keeps its own counts, so treat them as a brake, not a wall.
const PER_IP_LIMIT = 60;            // requests per IP per window
const WINDOW_MS = 10 * 60 * 1000;   // 10 minutes
const DAILY_LIMIT = 2000;           // requests per day for this Worker instance
const hits = new Map();
let day = { date: "", count: 0 };

function limited(ip) {
  const now = Date.now();
  const today = new Date().toISOString().slice(0, 10);
  if (day.date !== today) day = { date: today, count: 0 };
  if (++day.count > DAILY_LIMIT) return "The AI has reached today's limit. Try again tomorrow.";
  const h = hits.get(ip) ?? { start: now, n: 0 };
  if (now - h.start > WINDOW_MS) { h.start = now; h.n = 0; }
  h.n++;
  hits.set(ip, h);
  if (hits.size > 5000) hits.clear();
  return h.n > PER_IP_LIMIT ? "Too many questions in a short time. Please wait a few minutes." : null;
}

function cors(origin, env) {
  const allowed = (env.ALLOWED_ORIGINS ? env.ALLOWED_ORIGINS.split(",").map((s) => s.trim()) : DEFAULT_ORIGINS);
  return {
    "Access-Control-Allow-Origin": allowed.includes(origin) ? origin : allowed[0],
    "Access-Control-Allow-Methods": "GET, POST, OPTIONS",
    "Access-Control-Allow-Headers": "Content-Type",
    "Access-Control-Max-Age": "86400",
    "Vary": "Origin",
  };
}

// Which Cloudflare data centre and visitor country handled the request (for diagnosing region blocks).
const where = (request) => {
  if (request.cf) return (request.cf.colo || "?") + " data centre, visitor in " + (request.cf.country || "?");
  const region = typeof process !== "undefined" && process.env ? process.env.VERCEL_REGION : "";
  return (region || "?") + " region, visitor in " + (request.headers.get("x-vercel-ip-country") || "?");
};

const json = (body, status, headers) => new Response(JSON.stringify(body), { status, headers: { ...headers, "Content-Type": "application/json" } });

// Only pass through the parts Gemini needs, with size caps, so the server can't be used as a general chatbot.
function cleanContents(contents) {
  if (!Array.isArray(contents) || contents.length === 0 || contents.length > 16) throw new Error("Invalid conversation.");
  return contents.map((c) => {
    if (!c || (c.role !== "user" && c.role !== "model") || !Array.isArray(c.parts) || c.parts.length > 8) throw new Error("Invalid message.");
    return {
      role: c.role,
      parts: c.parts.map((p) => {
        const out = {};
        if (typeof p.text === "string") {
          if (c.role === "user" && p.text.length > 600) throw new Error("Message too long.");
          out.text = p.text.slice(0, 4000);
        }
        if (p.functionCall && typeof p.functionCall.name === "string") out.functionCall = { name: p.functionCall.name, args: p.functionCall.args ?? {} };
        if (p.functionResponse && typeof p.functionResponse.name === "string") {
          if (JSON.stringify(p.functionResponse.response ?? {}).length > 8000) throw new Error("Tool result too large.");
          out.functionResponse = { name: p.functionResponse.name, response: p.functionResponse.response ?? {} };
        }
        if (typeof p.thoughtSignature === "string") out.thoughtSignature = p.thoughtSignature;
        return out;
      }),
    };
  });
}

async function gemini(env, body) {
  const models = [env.GEMINI_MODEL || DEFAULT_MODEL];
  if (!env.GEMINI_MODEL) models.push(FALLBACK_MODEL);
  let last = "";
  for (const model of models) {
    const res = await fetch("https://generativelanguage.googleapis.com/v1beta/models/" + encodeURIComponent(model) + ":generateContent", {
      method: "POST",
      headers: { "Content-Type": "application/json", "x-goog-api-key": env.GEMINI_API_KEY },
      body: JSON.stringify(body),
    });
    const data = await res.json().catch(() => ({}));
    if (res.ok) {
      const content = data?.candidates?.[0]?.content;
      if (!content) throw Object.assign(new Error("Gemini returned no answer (" + (data?.candidates?.[0]?.finishReason || data?.promptFeedback?.blockReason || "empty") + ")."), { status: 502 });
      return { content: { role: "model", parts: content.parts ?? [] }, model };
    }
    last = (data?.error?.message || "").slice(0, 200);
    // Try the fallback model only when this model is unknown or not available to this key.
    if (res.status === 404 || (res.status === 400 && /model/i.test(last)) || res.status === 403) continue;
    throw Object.assign(new Error("Gemini error " + res.status + ": " + last), { status: res.status === 429 ? 429 : 502 });
  }
  throw Object.assign(new Error("No Gemini model available to this key: " + last), { status: 502 });
}

async function handle(request, env) {
  {
    const url = new URL(request.url);
    // Last path segment: "/check" on Cloudflare, "/api/check" on Vercel.
    const route = url.pathname.split("/").filter(Boolean).pop() || "check";
    const origin = request.headers.get("Origin") || "";
    const headers = cors(origin, env);
    if (request.method === "OPTIONS") return new Response(null, { status: 204, headers });
    if (!env.GEMINI_API_KEY) return json({ error: "The AI server has no GEMINI_API_KEY yet. Add it in the hosting settings and redeploy." }, 500, headers);

    const ip = request.headers.get("CF-Connecting-IP") || (request.headers.get("x-forwarded-for") || "").split(",")[0].trim() || "unknown";
    const tooMany = limited(ip);
    if (tooMany) return json({ error: tooMany }, 429, headers);

    try {
      if (request.method === "GET" && route === "check") {
        const r = await gemini(env, {
          systemInstruction: { parts: [{ text: CLASSIFY_PROMPT }] },
          contents: [{ role: "user", parts: [{ text: "aircond bocor air" }] }],
          generationConfig: { responseMimeType: "application/json" },
        });
        const answer = (r.content.parts || []).map((p) => p.text || "").join("");
        return json({ ok: true, model: r.model, test: "aircond bocor air", answer, ranFrom: where(request) }, 200, headers);
      }

      if (request.method !== "POST") return json({ error: "Not found." }, 404, headers);
      const allowed = (env.ALLOWED_ORIGINS ? env.ALLOWED_ORIGINS.split(",").map((s) => s.trim()) : DEFAULT_ORIGINS);
      if (!allowed.includes(origin)) return json({ error: "This AI server only answers the JiranLink website." }, 403, headers);
      const raw = await request.text();
      if (raw.length > 40000) return json({ error: "Request too large." }, 413, headers);
      const body = JSON.parse(raw || "{}");

      if (route === "classify") {
        const text = String(body.text || "").trim();
        if (!text || text.length > 300) return json({ error: "Text must be 1 to 300 characters." }, 400, headers);
        const r = await gemini(env, {
          systemInstruction: { parts: [{ text: CLASSIFY_PROMPT }] },
          contents: [{ role: "user", parts: [{ text }] }],
          generationConfig: { responseMimeType: "application/json" },
        });
        return json({ content: r.content, model: r.model }, 200, headers);
      }

      if (route === "agent") {
        const r = await gemini(env, {
          systemInstruction: { parts: [{ text: AGENT_PROMPT }] },
          tools: [{ functionDeclarations: AGENT_TOOLS }],
          contents: cleanContents(body.contents),
        });
        return json({ content: r.content, model: r.model }, 200, headers);
      }

      return json({ error: "Not found." }, 404, headers);
    } catch (e) {
      const msg = e.message || "AI server error.";
      const hint = /location is not supported/i.test(msg)
        ? " Google blocked the server location this ran from (" + where(request) + "). Host the AI server in a supported region (see README)."
        : "";
      return json({ error: msg + hint, ranFrom: where(request) }, e.status || 400, headers);
    }
  }
}

export { handle };
